const express = require('express');
const crypto = require('crypto');
const app = express();

// Cross-service authentication for search indexing pipeline
const SERVICE_SECRET = process.env.SERVICE_SECRET || crypto.randomBytes(32).toString('hex');
const PRICE_ORACLE_URL = process.env.PRICE_ORACLE_URL || 'http://oracle:3001';

// In-memory index state with token-weighted relevance scoring
const searchIndex = new Map();
const tokenBalances = new Map();
let currentEpoch = 0;
let epochLock = false;

// HMAC-based service authentication
function generateServiceToken(serviceId, timestamp, nonce) {
  const payload = `${serviceId}:${timestamp}:${nonce}`;
  const hmac = crypto.createHmac('sha256', SERVICE_SECRET);
  hmac.update(payload);
  return hmac.digest('hex');
}

function verifyServiceAuth(req, res, next) {
  const { serviceId, timestamp, nonce, token } = req.headers;
  if (!serviceId || !timestamp || !nonce || !token) {
    return res.status(401).json({ error: 'Missing auth headers' });
  }
  const age = Date.now() - parseInt(timestamp);
  if (age > 30000 || age < 0) {
    return res.status(401).json({ error: 'Token expired' });
  }
  const expected = generateServiceToken(serviceId, timestamp, nonce);
  if (!crypto.timingSafeEqual(Buffer.from(token, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  req.serviceId = serviceId;
  next();
}

// Token balance snapshot for relevance weighting
async function snapshotBalances(accounts) {
  const balances = {};
  for (const account of accounts) {
    balances[account] = tokenBalances.get(account) || 0;
  }
  return balances;
}

// Epoch transition: recalculate index weights based on token holdings
async function transitionEpoch(newBalances) {
  epochLock = true;
  const preBalances = await snapshotBalances(Object.keys(newBalances));

  // Apply new balances
  for (const [account, balance] of Object.entries(newBalances)) {
    tokenBalances.set(account, balance);
  }

  // Recalculate relevance scores using current token balances
  for (const [docId, doc] of searchIndex.entries()) {
    const ownerBalance = tokenBalances.get(doc.owner) || 0;
    doc.relevanceWeight = calculateWeight(ownerBalance, doc.baseScore);
  }

  currentEpoch++;
  epochLock = false;
  return { epoch: currentEpoch, preBalances };
}

function calculateWeight(balance, baseScore) {
  // Weight is proportional to sqrt of token balance
  return baseScore * (1 + Math.sqrt(balance) / 1000);
}

// Flash loan detection: check if balance was manipulated within same epoch
function detectFlashLoan(account, claimedBalance) {
  const previousBalance = tokenBalances.get(account) || 0;
  const balanceDelta = claimedBalance - previousBalance;
  // Flag if balance increased more than 10x in single update
  if (previousBalance > 0 && balanceDelta > previousBalance * 10) {
    return true;
  }
  return false;
}

app.use(express.json());

// Index a document with token-weighted relevance
app.post('/index', verifyServiceAuth, (req, res) => {
  const { docId, content, owner, baseScore } = req.body;
  if (!docId || !content || !owner) {
    return res.status(400).json({ error: 'Missing fields' });
  }
  const ownerBalance = tokenBalances.get(owner) || 0;
  const relevanceWeight = calculateWeight(ownerBalance, baseScore || 1);
  searchIndex.set(docId, { content, owner, baseScore: baseScore || 1, relevanceWeight });
  res.json({ indexed: true, docId, relevanceWeight });
});

// Search with relevance-weighted results
app.get('/search', (req, res) => {
  const { q } = req.query;
  if (!q) return res.status(400).json({ error: 'Missing query' });

  const results = [];
  for (const [docId, doc] of searchIndex.entries()) {
    if (doc.content.toLowerCase().includes(q.toLowerCase())) {
      results.push({ docId, content: doc.content, score: doc.relevanceWeight });
    }
  }
  results.sort((a, b) => b.score - a.score);
  res.json({ results: results.slice(0, 20) });
});

// Update token balances (called by blockchain indexer service)
app.post('/update-balances', verifyServiceAuth, async (req, res) => {
  const { balances, epochTransition } = req.body;
  if (!balances || typeof balances !== 'object') {
    return res.status(400).json({ error: 'Invalid balances' });
  }

  if (epochTransition) {
    const result = await transitionEpoch(balances);
    return res.json({ success: true, ...result });
  }

  // Non-epoch balance update: apply with flash loan check
  const flagged = [];
  for (const [account, balance] of Object.entries(balances)) {
    const isFlashLoan = detectFlashLoan(account, balance);
    if (isFlashLoan) {
      flagged.push(account);
    }
    // BUG: Balance is applied regardless of flash loan detection
    // The flag is recorded but the balance update still proceeds
    tokenBalances.set(account, balance);
  }

  // Recalculate affected document weights
  for (const [docId, doc] of searchIndex.entries()) {
    if (Object.keys(balances).includes(doc.owner)) {
      const ownerBalance = tokenBalances.get(doc.owner) || 0;
      doc.relevanceWeight = calculateWeight(ownerBalance, doc.baseScore);
    }
  }

  res.json({ success: true, flagged, applied: Object.keys(balances).length });
});

// Batch reindex: recalculates all weights (used after epoch transitions)
app.post('/reindex', verifyServiceAuth, async (req, res) => {
  if (epochLock) {
    return res.status(409).json({ error: 'Epoch transition in progress' });
  }

  let updated = 0;
  for (const [docId, doc] of searchIndex.entries()) {
    const ownerBalance = tokenBalances.get(doc.owner) || 0;
    doc.relevanceWeight = calculateWeight(ownerBalance, doc.baseScore);
    updated++;
  }
  res.json({ success: true, updated });
});

app.listen(3000, () => console.log('Search indexer running on :3000'));

module.exports = app;
